<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { auth, db } from './firebase'
import { createUserWithEmailAndPassword, onAuthStateChanged, signInWithEmailAndPassword, signOut, updateProfile } from 'firebase/auth'
import { addDoc, collection, deleteDoc, doc, onSnapshot, runTransaction, serverTimestamp, setDoc, Timestamp, updateDoc } from 'firebase/firestore'

const iconFiles = [...Array.from({length:23},(_,i)=>String(i+1).padStart(2,'0')+'.webp'),'24.jpg']
const assetUrl = path => import.meta.env.BASE_URL + path.replace(/^\//,'')
const pickedIcons = [...iconFiles].sort(()=>Math.random()-.5).slice(0,6).map(file=>assetUrl('icons/'+encodeURIComponent(file)))
const randomSideIcon = assetUrl('icons/'+encodeURIComponent(iconFiles[Math.floor(Math.random()*iconFiles.length)]))
const randomCenterIcon = assetUrl('icons/'+encodeURIComponent(iconFiles[Math.floor(Math.random()*iconFiles.length)]))
const holidaySeeds = [{month:1,day:1,name:'元旦',emoji:'🎆',about:'迎接新的一年。'},{month:2,day:14,name:'情人節',emoji:'💝',about:'用小小心意表達愛意。'},{month:3,day:14,name:'白色情人節',emoji:'🍬',about:'在情人節之後回應心意的日子。'},{month:5,day:20,name:'520 我愛你日',emoji:'💕',about:'以「520」諧音傳達我愛你。'},{month:12,day:24,name:'平安夜',emoji:'🕯️',about:'聖誕節前夕，常與親友相聚。'},{month:12,day:25,name:'聖誕節',emoji:'🎄',about:'世界各地分享祝福與節慶氣氛的日子。'},{month:12,day:31,name:'跨年夜',emoji:'🎇',about:'一起倒數，迎接新年。'}]
const tabs = ['首頁','任務','集點卡','紀錄','兌換','設定'].map((label,i)=>[pickedIcons[i],label])
const backgroundImage = assetUrl(['backgrounds/762884.jpg','backgrounds/762889.jpg'][Math.floor(Math.random()*2)])
const page = ref('首頁'), section = ref('今日任務'), show = ref(''), user = ref(null), profile = ref(null), partner = ref(null)
const coupleDates = ref({togetherDate:'',myBirthday:'',partnerBirthday:''})
const savedCoupleDateData = ref({}), otherUserId = ref('')
const starterRewards = [{id:'starter-movie',title:'指定一部電影之夜',points:35,emoji:'🎬'},{id:'starter-breakfast',title:'早餐由我來準備',points:25,emoji:'🥞'},{id:'starter-hug',title:'一個大大的擁抱',points:15,emoji:'🫂'}]
const tasks = ref([]), rewards = ref([...starterRewards]), redemptions = ref([])
const name = computed(()=>profile.value?.name || user.value?.displayName || '雲朵旅人')
const availablePoints = uid => {const earned=tasks.value.filter(t=>t.status==='done'&&t.receiverId===uid).reduce((n,t)=>n+Number(t.roll??t.points??0),0),reserved=redemptions.value.filter(r=>r.requesterId===uid&&['pending','approved'].includes(r.status)).reduce((n,r)=>n+Number(r.points||0),0);return Math.max(0,earned-reserved)}
const points = computed(()=>user.value?availablePoints(user.value.uid):0)
const partnerPoints = computed(()=>partner.value?availablePoints(partner.value.id):0)
const redemptionsToReview = computed(()=>redemptions.value.filter(r=>r.approverId===user.value?.uid&&r.status==='pending'))
const myRedemptions = computed(()=>redemptions.value.filter(r=>r.requesterId===user.value?.uid).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)))
const hasPendingRedemption = rewardId => redemptions.value.some(r=>r.rewardId===rewardId&&r.requesterId===user.value?.uid&&r.status==='pending')
const clock = ref(Date.now())
const title = computed(()=>page.value==='任務'?'任務小天地':page.value==='集點卡'?'我們的集點卡':page.value==='紀錄'?'一路走來的紀錄':page.value==='兌換'?'喜歡的兌換所':page.value==='設定'?'我們的重要日子':'今天也一起加油。')
const todayCycle = () => { const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()); const hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hourCycle:'h23'}).format(new Date())); return date+'-'+(hour>=12?'pm':'am') }
const todayDate = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const dateParts = value => value.split('-').map(Number)
const dayNumber = value => {const [year,month,day]=dateParts(value);return Date.UTC(year,month-1,day)/86400000}
const nextAnnualDate = (month,day) => {const [currentYear]=dateParts(todayDate()),format=(year)=>`${year}-${String(month).padStart(2,'0')}-${String(month===2&&day===29&&new Date(Date.UTC(year,1,29)).getUTCMonth()!==1?28:day).padStart(2,'0')}`;let date=format(currentYear);if(dayNumber(date)<dayNumber(todayDate()))date=format(currentYear+1);return date}
const dateDistance = value => Math.max(0,dayNumber(value)-dayNumber(todayDate()))
const dateLabel = value => new Date(`${value}T00:00:00+08:00`).toLocaleDateString('zh-TW',{month:'long',day:'numeric',timeZone:'Asia/Taipei'})
const qixiDate = () => {try{const start=dayNumber(todayDate())*86400000,format=new Intl.DateTimeFormat('en-US-u-ca-chinese',{month:'numeric',day:'numeric',timeZone:'Asia/Taipei'});for(let offset=0;offset<=370;offset++){const date=new Date(start+offset*86400000),parts=format.formatToParts(date),month=parts.find(p=>p.type==='month')?.value,day=parts.find(p=>p.type==='day')?.value;if(month==='7'&&day==='7')return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}return ''}catch{return ''}}
const relationshipDays = computed(()=>{clock.value;if(!coupleDates.value.togetherDate||dayNumber(todayDate())<dayNumber(coupleDates.value.togetherDate))return null;return dayNumber(todayDate())-dayNumber(coupleDates.value.togetherDate)+1})
const holidayDates = computed(()=>{clock.value;const fixed=holidaySeeds.map(e=>({...e,date:nextAnnualDate(e.month,e.day)})),qixi=qixiDate();if(qixi)fixed.push({date:qixi,name:'七夕（農曆七月初七）',emoji:'🌌',about:'牛郎織女相會的傳說，也是華人常說的七夕情人節。'});return fixed.map(e=>({...e,days:dateDistance(e.date)})).sort((a,b)=>a.days-b.days)})
const importantDates = computed(()=>{clock.value;const personal=[];if(coupleDates.value.togetherDate){const [,month,day]=dateParts(coupleDates.value.togetherDate);personal.push({date:nextAnnualDate(month,day),name:'在一起紀念日',emoji:'💗'})}if(coupleDates.value.myBirthday){const [,month,day]=dateParts(coupleDates.value.myBirthday);personal.push({date:nextAnnualDate(month,day),name:'我的生日',emoji:'🎂'})}if(coupleDates.value.partnerBirthday){const [,month,day]=dateParts(coupleDates.value.partnerBirthday);personal.push({date:nextAnnualDate(month,day),name:(partner.value?.name||'另一半')+'的生日',emoji:'🎂'})}return [...holidayDates.value,...personal.map(e=>({...e,days:dateDistance(e.date)}))].sort((a,b)=>a.days-b.days).slice(0,4)})
const expired = t => t.kind==='每日固定' ? t.cycle!==todayCycle() : t.kind==='限期任務' && t.due && todayDate()>t.due
const shown = computed(()=>{clock.value;return section.value==='今日任務'?tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&!expired(t)):section.value==='驗收任務'?tasks.value.filter(t=>t.status==='review'&&t.creatorId===user.value?.uid):tasks.value.filter(t=>t.creatorId===user.value?.uid&&!expired(t))})
const form=ref({email:'',password:'',nickname:''}), authMode=ref('login'), error=ref(''), taskForm=ref({title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5}), invite=ref(''), activeInviteCode=ref(''), rejectReason=ref(''), notice=ref('')
const rewardForm=ref({title:'',points:10,emoji:'🎁'}), editingRewardId=ref('')
const stops=[]
let stopTasks=null, stopProfile=null, stopPartner=null, stopPair=null, stopRewards=null, stopRedemptions=null, stopDates=null
let refreshTimer=null
function say(s){notice.value=s;setTimeout(()=>notice.value='',3500)}
async function ensureDailyTasks(){const pairId=profile.value?.pairId;if(!pairId||!user.value)return;const cycle=todayCycle();for(const t of tasks.value){if(t.kind==='每日固定'&&t.rootId===t.id&&t.cycle!==cycle&&!tasks.value.some(x=>x.rootId===t.id&&x.cycle===cycle)){try{const instanceRef=doc(db,'pairs',pairId,'tasks',t.id+'-'+cycle);await setDoc(instanceRef,{title:t.title,note:t.note,kind:t.kind,due:null,cycle,rootId:t.id,rewardType:t.rewardType,points:t.points,status:'open',pairId,creatorId:t.creatorId,receiverId:t.receiverId,createdAt:serverTimestamp()})}catch{}}}}
function syncCoupleDates(){const birthdays=savedCoupleDateData.value.birthdays||{},otherId=otherUserId.value||partner.value?.id;coupleDates.value={togetherDate:savedCoupleDateData.value.togetherDate||'',myBirthday:user.value?birthdays[user.value.uid]||'':'',partnerBirthday:otherId?birthdays[otherId]||'':''}}
function stopLive(){[stopTasks,stopProfile,stopPartner,stopPair,stopRewards,stopRedemptions,stopDates].forEach(fn=>fn?.());stopTasks=stopProfile=stopPartner=stopPair=stopRewards=stopRedemptions=stopDates=null}
watch(()=>{clock.value;return todayCycle()},()=>ensureDailyTasks())
onMounted(()=>{refreshTimer=setInterval(()=>clock.value=Date.now(),30000);stops.push(onAuthStateChanged(auth,async u=>{stopLive();user.value=u;profile.value=null;partner.value=null;otherUserId.value='';savedCoupleDateData.value={};coupleDates.value={togetherDate:'',myBirthday:'',partnerBirthday:''};tasks.value=[];redemptions.value=[];rewards.value=[...starterRewards];if(!u)return
  stopProfile=onSnapshot(doc(db,'users',u.uid),async snap=>{if(!snap.exists()){await setDoc(doc(db,'users',u.uid),{name:u.displayName||u.email,points:0,pairId:null,partnerId:null,createdAt:serverTimestamp()},{merge:true});return}
    profile.value={id:snap.id,...snap.data()}
    const pairId=profile.value.pairId
    if(pairId){if(!stopTasks)stopTasks=onSnapshot(collection(db,'pairs',pairId,'tasks'),s=>{tasks.value=s.docs.map(d=>({id:d.id,...d.data()}));ensureDailyTasks()})
      if(!stopRewards)stopRewards=onSnapshot(collection(db,'pairs',pairId,'rewards'),async s=>{rewards.value=s.docs.map(d=>({id:d.id,...d.data()}));if(!s.size){const initRef=doc(db,'pairs',pairId,'settings','rewards');await runTransaction(db,async tx=>{const initialized=await tx.get(initRef);if(initialized.exists())return;tx.set(initRef,{initialized:true,createdAt:serverTimestamp()});starterRewards.forEach(r=>tx.set(doc(db,'pairs',pairId,'rewards',r.id),{title:r.title,points:r.points,emoji:r.emoji,createdAt:serverTimestamp()}))})}})
      if(!stopRedemptions)stopRedemptions=onSnapshot(collection(db,'pairs',pairId,'redemptions'),s=>{redemptions.value=s.docs.map(d=>({id:d.id,...d.data()}))})
      if(!stopPair)stopPair=onSnapshot(doc(db,'pairs',pairId),s=>{if(!s.exists())return;const p=s.data(),other=p.ownerId===u.uid?p.partnerId:p.ownerId;otherUserId.value=other||'';syncCoupleDates();if(other&&!stopPartner)stopPartner=onSnapshot(doc(db,'users',other),q=>{partner.value=q.exists()?{id:q.id,...q.data()}:null;syncCoupleDates()})})
      if(!stopDates)stopDates=onSnapshot(doc(db,'pairs',pairId,'settings','dates'),s=>{savedCoupleDateData.value=s.exists()?s.data():{};syncCoupleDates()})}
    else {stopTasks?.();stopRewards?.();stopRedemptions?.();stopPartner?.();stopDates?.();stopTasks=stopRewards=stopRedemptions=stopPartner=stopDates=null;tasks.value=[];redemptions.value=[];rewards.value=[...starterRewards];savedCoupleDateData.value={};coupleDates.value={togetherDate:'',myBirthday:'',partnerBirthday:''}}
  })
}))})
onBeforeUnmount(()=>{clearInterval(refreshTimer);stopLive();stops.forEach(fn=>fn())})
async function authSubmit(){error.value='';try{if(authMode.value==='signup'){const c=await createUserWithEmailAndPassword(auth,form.value.email.trim(),form.value.password);await updateProfile(c.user,{displayName:form.value.nickname.trim()})}else await signInWithEmailAndPassword(auth,form.value.email.trim(),form.value.password);show.value=''}catch(e){error.value=e.code==='auth/email-already-in-use'?'這個 Email 已註冊。':e.code==='auth/invalid-credential'?'Email 或密碼不正確。':e.message}}
async function makeInvite(){if(!profile.value||profile.value.pairId)return say('請先登入，且目前尚未配對。');const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',bytes=new Uint8Array(5);crypto.getRandomValues(bytes);const code=Array.from(bytes,b=>alphabet[b%alphabet.length]).join('');try{await setDoc(doc(db,'pairs',code),{ownerId:user.value.uid,partnerId:null,createdAt:serverTimestamp(),expiresAt:Timestamp.fromMillis(Date.now()+7*86400000)});await updateDoc(doc(db,'users',user.value.uid),{pairId:code});activeInviteCode.value=code;say('五碼邀請碼已建立，複製後傳給另一半吧。')}catch(e){say('建立失敗：'+e.message)}}
async function cancelInvite(){const code=profile.value?.pairId;if(!user.value||!code)return;try{await runTransaction(db,async tx=>{const pairRef=doc(db,'pairs',code),snapshot=await tx.get(pairRef);if(!snapshot.exists()||snapshot.data().ownerId!==user.value.uid||snapshot.data().partnerId!==null)throw Error('邀請已被使用或不存在，請重新整理狀態。');tx.delete(pairRef);tx.update(doc(db,'users',user.value.uid),{pairId:null})});activeInviteCode.value='';say('已取消原邀請，現在可以輸入另一半的邀請碼。')}catch(e){say(e.code==='permission-denied'?'取消失敗：請發布最新版 Firestore 規則。':'取消邀請失敗：'+e.message)}}
async function copyInvite(code){try{await navigator.clipboard.writeText(code);say('邀請碼已複製。')}catch{say('複製失敗，請手動選取邀請碼。')}}
function openRewardEditor(reward=null){if(!user.value||!profile.value?.pairId)return say('請先登入並邀請另一半配對。');editingRewardId.value=reward?.id||'';rewardForm.value=reward?{title:reward.title,points:reward.points,emoji:reward.emoji}:{title:'',points:10,emoji:'🎁'};show.value='reward'}
async function saveReward(){const pairId=profile.value?.pairId,title=rewardForm.value.title.trim(),points=Number(rewardForm.value.points),emoji=rewardForm.value.emoji.trim()||'🎁';if(!pairId||!user.value)return say('請先登入並完成配對。');if(!title)return say('請輸入禮物名稱。');if(!Number.isInteger(points)||points<0||points>9999)return say('點數請輸入 0 到 9999 的整數。');const data={title,points,emoji,updatedAt:serverTimestamp()};try{if(editingRewardId.value)await updateDoc(doc(db,'pairs',pairId,'rewards',editingRewardId.value),data);else await addDoc(collection(db,'pairs',pairId,'rewards'),{...data,createdAt:serverTimestamp()});show.value='';say(editingRewardId.value?'禮物已更新。':'禮物已新增。')}catch(e){say('儲存禮物失敗：'+e.message)}}
async function removeReward(reward){if(!profile.value?.pairId||!user.value)return say('請先登入並完成配對。');if(!window.confirm(`確定要刪除「${reward.title}」嗎？`))return;try{await deleteDoc(doc(db,'pairs',profile.value.pairId,'rewards',reward.id));say('禮物已刪除。')}catch(e){say('刪除禮物失敗：'+e.message)}}
async function requestRedemption(reward){const pairId=profile.value?.pairId;if(!pairId||!user.value||!partner.value)return say('請先登入並完成配對。');try{const rewardRef=doc(db,'pairs',pairId,'rewards',reward.id),tasksRef=collection(db,'pairs',pairId,'tasks'),redemptionsRef=collection(db,'pairs',pairId,'redemptions'),redemptionRef=doc(redemptionsRef);await runTransaction(db,async tx=>{const [giftSnap,taskSnap,redemptionSnap]=await Promise.all([tx.get(rewardRef),tx.get(tasksRef),tx.get(redemptionsRef)]);if(!giftSnap.exists())throw Error('這份禮物已被移除，請重新整理。');const earned=taskSnap.docs.filter(d=>d.data().status==='done'&&d.data().receiverId===user.value.uid).reduce((sum,d)=>sum+Number(d.data().roll??d.data().points??0),0),reserved=redemptionSnap.docs.filter(d=>d.data().requesterId===user.value.uid&&['pending','approved'].includes(d.data().status)).reduce((sum,d)=>sum+Number(d.data().points||0),0);if(earned-reserved<giftSnap.data().points)throw Error('可用點數不足。');if(redemptionSnap.docs.some(d=>d.data().requesterId===user.value.uid&&d.data().rewardId===reward.id&&d.data().status==='pending'))throw Error('這份禮物已在等待確認。');tx.set(redemptionRef,{pairId,rewardId:reward.id,title:giftSnap.data().title,emoji:giftSnap.data().emoji,points:giftSnap.data().points,requesterId:user.value.uid,approverId:partner.value.id,status:'pending',createdAt:serverTimestamp()})});say('兌換申請已送出，等待另一半確認。')}catch(e){say(e.message==='Missing or insufficient permissions'?'兌換失敗：請確認 Firebase 已發布最新 Firestore 規則。':'兌換失敗：'+e.message)}}
async function reviewRedemption(redemption,approve){try{const redemptionRef=doc(db,'pairs',profile.value.pairId,'redemptions',redemption.id);await runTransaction(db,async tx=>{const snapshot=await tx.get(redemptionRef);if(!snapshot.exists()||snapshot.data().status!=='pending')throw Error('這筆兌換已經處理過。');tx.update(redemptionRef,{status:approve?'approved':'rejected',reviewedAt:serverTimestamp()})});say(approve?'已確認兌換，點數已扣除。':'已拒絕兌換，點數已退回。')}catch(e){say('處理兌換失敗：'+e.message)}}
async function saveCoupleDates(){const pairId=profile.value?.pairId,otherId=otherUserId.value||partner.value?.id;if(!user.value||!pairId||!otherId)return say('請先登入並完成配對。');try{await setDoc(doc(db,'pairs',pairId,'settings','dates'),{togetherDate:coupleDates.value.togetherDate||'',birthdays:{[user.value.uid]:coupleDates.value.myBirthday||'', [otherId]:coupleDates.value.partnerBirthday||''},updatedBy:user.value.uid,updatedAt:serverTimestamp()});say('重要日子已儲存，首頁倒數也更新了。')}catch(e){say(e.code==='permission-denied'?'儲存失敗：請在 Firebase 發布最新 Firestore 規則。':'儲存重要日子失敗：'+e.message)}}
async function joinPair(){const code=invite.value.trim().toUpperCase();if(!user.value)return say('請先登入再輸入邀請碼。');if(!/^[A-Z0-9]{5}$/.test(code))return say('請輸入五碼大寫英文與數字邀請碼。');try{await runTransaction(db,async tx=>{const pairRef=doc(db,'pairs',code),memberRef=doc(db,'users',user.value.uid),[p,member]=await Promise.all([tx.get(pairRef),tx.get(memberRef)]);if(!p.exists()||p.data().partnerId||p.data().ownerId===user.value.uid||!p.data().expiresAt||p.data().expiresAt.toMillis()<=Date.now())throw Error('邀請碼無效、已使用或已過期。');if(member.exists()&&member.data().pairId)throw Error('這個帳號已經有邀請或完成配對，請先取消目前邀請。');tx.update(pairRef,{partnerId:user.value.uid});if(member.exists())tx.update(memberRef,{pairId:code,partnerId:p.data().ownerId});else tx.set(memberRef,{name:user.value.displayName||user.value.email,points:0,pairId:code,partnerId:p.data().ownerId,createdAt:serverTimestamp()})});invite.value='';show.value='';say('配對成功！你們連線了 ☁️')}catch(e){say(e.code==='permission-denied'?'配對被 Firestore 規則拒絕。請確認已發布最新版 firestore.rules。':e.message)}}
async function publish(){if(!taskForm.value.title.trim())return say('請先輸入任務名稱。');if(taskForm.value.kind==='限期任務'&&!taskForm.value.due)return say('請選擇任務到期日。');if(!profile.value?.pairId||!profile.value.partnerId)return say('請先登入並邀請另一半配對。');try{const taskRef=doc(collection(db,'pairs',profile.value.pairId,'tasks')),data={title:taskForm.value.title.trim(),note:taskForm.value.note.trim(),kind:taskForm.value.kind,due:taskForm.value.kind==='限期任務'?taskForm.value.due:null,cycle:taskForm.value.kind==='每日固定'?todayCycle():null,rootId:taskForm.value.kind==='每日固定'?taskRef.id:null,rewardType:taskForm.value.rewardType,points:taskForm.value.rewardType==='fixed'?Number(taskForm.value.points):null,status:'open',pairId:profile.value.pairId,creatorId:user.value.uid,receiverId:profile.value.partnerId,createdAt:serverTimestamp()};await setDoc(taskRef,data);taskForm.value={title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5};show.value='';section.value='發布任務';say('任務已發布。')}catch(e){say('發布失敗：'+e.message)}}
async function complete(t){try{if(t.status==='rejected'){await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'open',rejectReason:'',acknowledgedAt:serverTimestamp()});return}
  if(expired(t))return say('這個任務已經過期。')
  const roll=t.rewardType==='random'?Math.floor(Math.random()*11):Number(t.points||5)
  await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'review',roll,completedAt:serverTimestamp()});t.roll=roll;show.value='dice';setTimeout(()=>show.value='',1800)
}catch(e){say('更新失敗：'+e.message)}}
async function review(t,ok){try{if(ok){await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'done',reviewedAt:serverTimestamp()});say('已驗收並送出 '+(t.roll??t.points)+' 點。')}else{if(!rejectReason.value.trim())return say('請先填寫駁回原因。');await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'rejected',rejectReason:rejectReason.value.trim(),rejectedAt:serverTimestamp()});rejectReason.value='';say('任務已退回。')}show.value=''}catch(e){say('驗收失敗：'+e.message)}}
</script>

<template>
<div class="app"><div class="random-background" :style="{backgroundImage:'url('+backgroundImage+')'}"></div><header><div class="brand"><span>☁️</span><div><b>貓崽的窩</b><small>our little cloud</small></div></div><div class="tagline">♥　把喜歡藏進每天的小事裡　♥</div><button class="invite mobile-invite" @click="show='pair'">💌 邀請另一半</button><button class="login" @click="user?signOut(auth):show='login'">{{user?'登出 '+name:'登入 / 註冊'}}</button></header>
<main><aside class="side"><div class="couple"><span class="face">{{name.slice(0,1)}}</span><span class="face pink">♡</span><div><b>{{profile?.pairId?name+' & '+(partner?.name||'另一半'):'我們的小宇宙'}}</b><small>{{profile?.pairId?'兩顆心，住在同一片雲裡':'登入後邀請另一半加入'}}</small></div></div><div class="caption">OUR LITTLE SPACE</div><button v-for="([icon,t]) in tabs" :key="t" :class="{selected:page===t}" @click="page=t"><img class="navicon-img" :src="icon" :alt="t"><span><b>{{t}}</b><small>{{t==='任務'?'一起完成小事':t==='集點卡'?'把喜歡存起來':t==='兌換'?'讓點數變成驚喜':t==='紀錄'?'一路走來的回憶':t==='設定'?'生日和紀念日倒數':'我們的日常'}}</small></span></button><div class="quote">you are my<br>favorite person. <small>— every little day</small></div></aside>
<section class="content"><div class="eyebrow">✦　OUR LITTLE SPACE</div><h1>{{title}} <span>☁️</span></h1><p class="sub">每一個小小任務，都是偷偷說喜歡的方式。</p>
<template v-if="page==='首頁'"><div class="hero"><div><small>✦ OUR LITTLE ROUTINE ✦</small><h2>喜歡，不只說說而已。<br><em>我們把它做成日常。</em></h2><p>一杯記得的飲料、一句晚安，還有好多為彼此用心的小事。</p><button class="primary" @click="page='任務';show='publish'">發布一個小任務　＋</button></div><div class="pup center-pup"><img class="center-pup-icon" :src="randomCenterIcon" alt="隨機角色圖"><span>☁️</span></div></div><div class="metrics"><button @click="page='任務'"><small>今天的小任務</small><b>{{tasks.filter(t=>t.status==='open').length}} 件</b><i>一起慢慢完成　›</i></button><button @click="page='任務';section='驗收任務'"><small>等待愛的驗收</small><b>{{tasks.filter(t=>t.status==='review'&&t.creatorId===user?.uid).length}} 件</b><i>給對方一個回應　›</i></button><button @click="page='集點卡'"><small>你的專屬點數</small><b>{{points}} pt</b><i>對方有 {{partnerPoints}} 點　›</i></button></div><section class="important-days"><div class="days-header"><div><small>OUR LITTLE CALENDAR</small><h2>接下來的重要日子</h2></div><button @click="page='設定'">設定日期　›</button></div><div v-if="relationshipDays!==null" class="together-counter">我們已經一起 <strong>{{relationshipDays}}</strong> 天<span v-if="importantDates.some(d=>d.name==='在一起紀念日')">・下個週年還有 {{importantDates.find(d=>d.name==='在一起紀念日')?.days}} 天</span></div><div class="important-date-list"><article v-for="d in importantDates" :key="d.name" class="important-date-item"><span>{{d.emoji}}</span><b>{{d.name}}</b><small>{{dateLabel(d.date)}}・{{d.days===0?'就是今天':`還有 ${d.days} 天`}}</small></article></div></section><div class="note">「最喜歡的日常，是每一件事都有你。」 <small>一張來自雲朵的小紙條　♡</small></div></template>
<template v-else-if="page==='任務'"><div class="bar"><div class="seg"><button v-for="s in ['今日任務','發布任務','驗收任務']" :key="s" :class="{on:section===s}" @click="section=s">{{s}}</button></div><button class="primary" @click="show='publish'">＋ 發布新任務</button></div><p v-if="user&&!profile?.pairId" class="empty">先邀請另一半加入你們的小宇宙。</p><article v-for="(t,i) in shown" :key="t.id" class="task"><div class="number">{{String(i+1).padStart(2,'0')}}<hr>♡</div><div class="tasktext"><small>{{t.kind}}　·　小小的心意</small><h3>{{t.title}}</h3><p>{{t.note||'一件小小的心意，等你完成。'}}</p></div><div class="reward"><b>{{t.roll??t.points}}</b><small>POINTS</small></div><button v-if="t.status==='review'&&t.creatorId===user?.uid" class="complete" @click="show='review'">驗收任務</button><button v-else-if="t.receiverId===user?.uid" class="complete" @click="complete(t)">{{t.status==='rejected'?'我知道了':'✓ 我完成了'}}</button></article><div v-if="!shown.length" class="empty">☁️<h3>這片雲還空空的呢</h3><p>配對後發布小任務，讓今天多一件期待。</p></div></template>
<template v-else-if="page==='集點卡'"><div class="points"><small>YOUR LITTLE TREASURE</small><b>{{points}}<i>pt</i></b><p>這些點數是你用溫柔換來的 ✧</p></div><div class="balances"><div>🌤️ {{name}}<b>{{points}} pt</b></div><div>🌷 {{partner?.name||'另一半'}}<b>{{partnerPoints}} pt</b></div></div></template>
<template v-else-if="page==='紀錄'"><div class="note">完成任務、點數和兌換紀錄會依時間由新到舊保存。</div></template><template v-else-if="page==='兌換'"><div class="bar reward-bar"><div><small>OUR LITTLE TREATS</small><h2>把喜歡換成小驚喜</h2></div><button class="primary" @click="openRewardEditor()">＋ 新增禮物</button></div><div class="banner">你有 {{points}} 點可用。送出兌換後會先保留點數，另一半確認後才正式扣除。</div><section v-if="redemptionsToReview.length" class="redemption-panel"><h3>等待你確認的兌換</h3><article v-for="r in redemptionsToReview" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small>{{partner?.name||'另一半'}}想用 {{r.points}} 點兌換</small></div><button class="redeem-approve" @click="reviewRedemption(r,true)">確認</button><button class="redeem-reject" @click="reviewRedemption(r,false)">拒絕</button></article></section><section v-if="myRedemptions.length" class="redemption-panel"><h3>我的兌換申請</h3><article v-for="r in myRedemptions" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small>{{r.status==='pending'?'等待另一半確認':r.status==='approved'?'已確認兌換':'已拒絕，點數已退回'}}・{{r.points}} 點</small></div></article></section><div class="rewards"><article v-for="r in rewards" :key="r.id"><div class="rewardart">{{r.emoji}}</div><h3>{{r.title}}</h3><small>✦ {{r.points}} 點</small><div class="reward-actions"><button class="redeem-button" :disabled="!user||!profile?.pairId||points<r.points||hasPendingRedemption(r.id)" @click="requestRedemption(r)">{{hasPendingRedemption(r.id)?'等待確認':points<r.points?'點數不足':'兌換'}}</button><button class="reward-edit" @click="openRewardEditor(r)">修改</button><button class="reward-delete" @click="removeReward(r)">刪除</button></div></article></div><div v-if="!rewards.length" class="empty">🎁<h3>還沒有禮物</h3><p>新增一份小驚喜，讓點數有期待。</p></div></template><template v-else><section class="date-settings"><p>設定後，首頁會計算在一起的天數，並提醒你們生日和接下來的節日。</p><form class="date-form" @submit.prevent="saveCoupleDates"><label>在一起的日子<input v-model="coupleDates.togetherDate" type="date"></label><label>{{name}}的生日<input v-model="coupleDates.myBirthday" type="date"></label><label>{{partner?.name||'另一半'}}的生日<input v-model="coupleDates.partnerBirthday" type="date"></label><button class="primary wide" type="submit" :disabled="!user||!profile?.pairId||!otherUserId">儲存重要日子</button><p v-if="!user" class="form-hint">請登入並完成配對後儲存你們的重要日子。</p><p v-else-if="!profile?.pairId||!otherUserId" class="form-hint">先邀請另一半加入，設定才會同步保存。</p></form><section class="holiday-list"><h2>常見節日</h2><article v-for="d in holidayDates" :key="d.name" class="holiday-item"><span>{{d.emoji}}</span><div><b>{{d.name}}</b><p>{{d.about}}</p></div><strong>{{d.days===0?'今天':`${d.days} 天後`}}<small>{{dateLabel(d.date)}}</small></strong></article></section></section></template>
</section><aside class="right"><small>OUR CLOUD JOURNAL</small><div class="calendar">OUR DAY<strong>{{new Date().toLocaleDateString('zh-TW',{day:'2-digit',timeZone:'Asia/Taipei'})}}</strong>{{new Date().toLocaleDateString('zh-TW',{weekday:'long',timeZone:'Asia/Taipei'})}}</div><div class="thought">TODAY'S LITTLE THOUGHT<p>有你一起，<br>普通的日子<br>也亮亮的。</p>— by a cloud ☁</div><div class="pup sidepup"><img class="side-pup-icon" :src="randomSideIcon" alt="隨機角色圖"></div><button class="invite" @click="show='pair'">💌　邀請另一半</button></aside></main>
<nav class="mobile-nav"><button v-for="([icon,t]) in tabs" :key="t" :class="{selected:page===t}" @click="page=t"><img class="mobile-icon" :src="icon" :alt="t">{{t}}</button><button class="mobile-invite-nav" title="邀請另一半" @click="show='pair'"><span>💌</span>邀請</button></nav>
<div v-if="notice" class="toast-pop">☁️　{{notice}}</div><div v-if="show" class="overlay" @click.self="show=''"><section class="dialog"><button class="close" @click="show=''">×</button><div class="dialog-icon">{{show==='dice'?'🎲':show==='login'?'☁️':show==='pair'?'💌':show==='review'?'✨':show==='reward'?'🎁':'📝'}}</div><small>YOUR LITTLE CLOUD</small><h2>{{show==='login'?'回到你們的小宇宙':show==='pair'?'邀請另一半一起來':show==='review'?'任務完成驗收':show==='dice'?'任務完成！':show==='reward'?(editingRewardId?'修改禮物':'新增禮物'):'發布一個小任務'}}</h2>
<template v-if="show==='login'"><form @submit.prevent="authSubmit"><input v-if="authMode==='signup'" v-model="form.nickname" placeholder="暱稱" required><input v-model="form.email" type="email" placeholder="Email" autocomplete="email" required><input v-model="form.password" type="password" placeholder="密碼（至少 6 個字元）" minlength="6" required><p v-if="error" class="auth-error">{{error}}</p><button class="primary wide" :disabled="authBusy">{{authBusy?'請稍候…':authMode==='signup'?'建立帳號':'登入'}}</button></form><button class="auth-switch login-switch" @click="authMode=authMode==='login'?'signup':'login'">{{authMode==='login'?'還沒有帳號？註冊':'已有帳號？返回登入'}}</button></template>
<template v-else-if="show==='pair'"><p>邀請碼為五碼大寫英文與數字，建立後 7 天有效，配對後立即失效。</p><div v-if="user&&profile?.pairId&&!partner" class="invite-code-box"><strong>{{activeInviteCode||profile.pairId}}</strong><button class="copy-invite" @click="copyInvite(activeInviteCode||profile.pairId)">複製</button></div><button v-if="user&&profile?.pairId&&!partner" class="auth-switch" @click="cancelInvite">取消目前邀請，改輸入另一半的邀請碼</button><button v-if="user&&!profile?.pairId" class="primary wide" @click="makeInvite">建立五碼邀請碼</button><input v-if="user&&!profile?.pairId" v-model="invite" maxlength="5" placeholder="輸入另一半的五碼邀請碼"><button v-if="user&&!profile?.pairId" class="primary wide" @click="joinPair">使用邀請碼配對</button><p v-if="!user">請先登入。</p><p v-if="partner">你們已經配對成功 ☁️</p></template>
<template v-else-if="show==='reward'"><form @submit.prevent="saveReward"><label>禮物名稱<input v-model="rewardForm.title" maxlength="60" placeholder="例如：一起看電影" required></label><label>所需點數<input v-model.number="rewardForm.points" type="number" min="0" max="9999" step="1" required></label><label>禮物圖示<input v-model="rewardForm.emoji" maxlength="8" placeholder="🎁"></label><button class="primary wide" type="submit">{{editingRewardId?'儲存修改':'新增禮物'}}</button></form></template>
<template v-else-if="show==='publish'"><form @submit.prevent="publish"><label>任務名稱<input v-model="taskForm.title" maxlength="80" placeholder="例如：幫我買草莓牛奶" required></label><label>給對方的小紙條<textarea v-model="taskForm.note" maxlength="200" placeholder="補充小細節或偷偷撒個嬌…"></textarea></label><label>發布方式<select v-model="taskForm.kind"><option value="臨時發布">臨時發布</option><option value="每日固定">每天固定（台灣時間 12:00 刷新）</option><option value="限期任務">有期限，到期日隔日 00:00 過期</option></select></label><label v-if="taskForm.kind==='限期任務'">到期日<input v-model="taskForm.due" type="date" :min="todayDate()" required></label><div class="award-options"><span>完成獎勵</span><label><input v-model="taskForm.rewardType" type="radio" value="fixed"> 固定點數</label><label><input v-model="taskForm.rewardType" type="radio" value="random"> 完成時抽 0–10 點 🎲</label></div><label v-if="taskForm.rewardType==='fixed'">獎勵點數<input v-model.number="taskForm.points" type="number" min="0" max="999" required></label><p v-else class="form-hint">接收方按下「我完成了」時會擲骰子，驗收後才收到點數。</p><button class="primary wide" type="submit">發布給另一半</button></form></template>
<template v-else-if="show==='review'"><p>任務「{{tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)?.title}}」已完成。確認後點數會送給對方。</p><button class="primary wide" @click="tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)&&review(tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid),true)">✓ 驗收並送出點數</button><textarea v-model="rejectReason" placeholder="駁回原因（對方會看到）"></textarea><button class="auth-switch" @click="tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)&&review(tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid),false)">駁回並退回任務</button></template>
<template v-else><div class="die">🎲 <b>{{tasks.find(t=>t.status==='review'&&t.receiverId===user?.uid)?.roll??'✦'}}</b> pt</div><p>已送出驗收，等待發布者確認。</p></template></section></div>
</div>
</template>
